function mazeBlocked(position){if(!mazeGrid)return false;const half=(MAZE_SIZE-1)/2,gx=Math.round(position.x/MAZE_CELL+half),gy=Math.round(position.z/MAZE_CELL+half);return gx<0||gy<0||gx>=MAZE_SIZE||gy>=MAZE_SIZE||mazeGrid[gy][gx]===1}
