function updateRootChase(dt){if(!chaseState||!rootChaser||dlg.open)return;const heart=mazeWorld(MAZE_SIZE-2,MAZE_SIZE-2),playerGround=new THREE.Vector3(camera.position.x,0,camera.position.z);if(playerGround.distanceTo(heart)<4.6){if(!chaseState.safe){chaseState.safe=true;const away=rootChaser.position.clone().sub(heart);away.y=0;if(away.length()<5.2)rootChaser.position.copy(heart.clone().add(away.length()>.01?away.normalize().multiplyScalar(5.2):new THREE.Vector3(-5.2,0,0)));document.querySelector('#prompt').textContent='THE HEART PROTECTS YOU — THE CREATURE CANNOT ENTER'}rootChaser.lookAt(camera.position.x,rootChaser.position.y,camera.position.z);return}else if(chaseState.safe){chaseState.safe=false;chaseState.pathTimer=0;document.querySelector('#prompt').textContent='YOU LEFT THE SAFE CHAMBER — RUN'}if(chaseState.headStart>0){chaseState.headStart-=dt;if(chaseState.headStart<=0){rootChaser.visible=true;document.querySelector('#prompt').textContent='RUN — THE PLAYROOM CREATURE FOLLOWED YOU'}return}chaseState.pathTimer-=dt;if(chaseState.pathTimer<=0){chaseState.path=findMazePath(rootChaser.position,camera.position);chaseState.waypoint=1;chaseState.pathTimer=.55}const cell=chaseState.path[chaseState.waypoint];if(cell){const target=mazeWorld(cell[0],cell[1]);target.y=0;const direction=target.clone().sub(rootChaser.position);if(direction.length()<.15)chaseState.waypoint++;else rootChaser.position.add(direction.normalize().multiplyScalar(dt*2.65))}rootChaser.lookAt(camera.position.x,rootChaser.position.y,camera.position.z);if(rootChaser.position.distanceTo(playerGround)<1.05){playMonsterJumpscare('root-stalker','Root Stalker','THE ROOT STALKER CAUGHT YOU',700);stability=Math.max(0,stability-20);const start=mazeWorld(1,1);camera.position.set(start.x,1.7,start.z);rootChaser.position.copy(start);chaseState.headStart=3;rootChaser.visible=false;document.querySelector('#prompt').textContent='IT CAUGHT YOU — RUN BEFORE IT WAKES AGAIN'}}
function startMazeEscape(){dlg.close();mazeEscape=true;scene.fog.color.setHex(0x4a0903);scene.fog.density=.032;const open=[];for(let y=0;y<MAZE_SIZE;y++)for(let x=0;x<MAZE_SIZE;x++)if(mazeGrid[y][x]===0){const p=mazeWorld(x,y);open.push(p);mazeEscapePlatforms.push({x:p.x,z:p.z,halfX:.82,halfZ:.82,top:.48})}const lava=new THREE.Mesh(new THREE.PlaneGeometry(MAZE_SIZE*MAZE_CELL,MAZE_SIZE*MAZE_CELL),new THREE.MeshStandardMaterial({color:0xff2705,emissive:0xc31302,emissiveIntensity:3.8,roughness:.35}));lava.rotation.x=-Math.PI/2;lava.position.y=.09;lava.name='maze lava';roomGroup.add(lava);const stones=new THREE.InstancedMesh(new THREE.BoxGeometry(1.65,.45,1.65),mat(0x392b22),open.length),matrix=new THREE.Matrix4();open.forEach((p,index)=>{matrix.makeTranslation(p.x,.255,p.z);stones.setMatrixAt(index,matrix)});stones.castShadow=true;stones.receiveShadow=true;roomGroup.add(stones);playerFeetY=.48;verticalVelocity=0;playerGrounded=true;camera.position.y=2.18;const heart=mazeWorld(MAZE_SIZE-2,MAZE_SIZE-2);spawnRootChaser(heart);chaseState.headStart=2;mazeChaosHandle=setInterval(()=>{if(mazeEscape)mazeShiftTimer=0},650);document.querySelector('#prompt').textContent='ESCAPE! SPACE TO JUMP · THE FLOOR IS LAVA';setTimeout(()=>controls.lock(),100)}
