function collectHandle(part,object){if(handlePieces.has(part))return;handlePieces.add(part);localStorage.setItem('cabin-handle-pieces',JSON.stringify([...handlePieces]));object.removeFromParent();updateHud();controls.unlock();if(handlePieces.size<3)message('A PIECE OF THE HANDLE',`Cold brass. ${3-handlePieces.size} piece${handlePieces.size===2?'':'s'} still missing.`);else{saved[0]=true;localStorage.setItem('cabin-3d-progress',JSON.stringify(saved));updateHud();message('THE HANDLE IS WHOLE','The inner door opens. It does not lead outside—it leads deeper into the cabin. On the wall: “YOU HAVE BEEN HERE BEFORE.”')}}
function rememberCabinSecret(id){cabinSecrets.add(id);localStorage.setItem('cabin-secret-chain',JSON.stringify([...cabinSecrets]));updateHud()}
function cabinChoicePuzzle(name,copy,correct,onSolve){controls.unlock();base('CABIN SECRET',name,copy);let chosen=[];const wrap=document.createElement('div');wrap.className='choices';[...correct].sort(()=>Math.random()-.5).forEach(word=>{const button=document.createElement('button');button.textContent=word;button.onclick=()=>{button.classList.add('used');chosen.push(word);feedback.textContent=chosen.join(' → ');if(chosen.length===correct.length){if(chosen.join()===correct.join())setTimeout(onSolve,450);else{feedback.textContent='The mechanism clicks, then resets.';setTimeout(()=>cabinChoicePuzzle(name,copy,correct,onSolve),900)}}};wrap.append(button)});body.append(wrap)}
function openCabinSecret(part){
 controls.unlock();
 if(part==='drawer'){if(cabinSecrets.has('compass'))return message('THE EMPTY DRAWER','Only the compass-shaped mark in the dust remains.');rememberCabinSecret('compass');return message('THE FALSE-BOTTOM DRAWER',`A compass and a note are taped underneath: “${puzzleRun.mapRoute.join(', then ')}.” Find the map in the Trophy Room.`)}
 if(part==='map'){if(!cabinSecrets.has('compass'))return message('THE MOUNTED MAP','The Bedroom drawer may contain the coordinates you need.');if(cabinSecrets.has('map-route'))return message('THE TRACED ROUTE',`The crossed trees read: ${puzzleRun.logOrder.join(' → ')}.`);return cabinChoicePuzzle('THE MOUNTED MAP','Follow this run’s two coordinates in their written order.',puzzleRun.mapRoute,()=>{rememberCabinSecret('map-route');message('A ROUTE THROUGH THE WOODS',`The tree symbols read: ${puzzleRun.logOrder.join(' → ')}. Return to the fireplace.`)})}
 if(part==='fireplace'){if(!cabinSecrets.has('map-route'))return message('THE THREE LOGS','The Trophy Room map reveals which log burns first.');if(!cabinSecrets.has('logs'))return cabinChoicePuzzle('THE LOG SEQUENCE','Place the logs in the order revealed by this run’s map.',puzzleRun.logOrder,()=>{rememberCabinSecret('logs');message('THE HEARTH OPENS','Something metallic glints beneath the ashes. Search again.')});if(!cabinSecrets.has('ash-key')){rememberCabinSecret('ash-key');return message('ASHES TO CODE','A heat-blackened key may fit the Cellar tackle box.')}return message('THE COLD FIREPLACE','The ashes have already given up their secret.')}
 if(part==='tackle'){if(cabinSecrets.has('batteries'))return message('THE OPEN TACKLE BOX','Only hooks and wrappers remain.');if(!cabinSecrets.has('ash-key'))return message('THE LOCKED TACKLE BOX','Its key has been exposed to intense heat.');rememberCabinSecret('batteries');return message('THE TACKLE BOX OPENS','Inside are batteries for the Workshop lantern.')}
 if(part==='lantern'){if(cabinSecrets.has('lantern'))return message('THE LANTERN’S SHADOW',`The shade projects: ${puzzleRun.windowWord.split('').join(' ')}.`);if(!cabinSecrets.has('batteries'))return message('THE DEAD LANTERN','The Cellar tackle box may contain batteries.');rememberCabinSecret('lantern');return message('THE LANTERN IGNITES',`Its shade projects ${puzzleRun.windowWord}. Take that word to the Main Cabin window.`)}
 if(part==='window'){if(cabinSecrets.has('escaped-window'))return message('THE UNCHAINED WINDOW','Cold forest air slips through the frame.');if(!cabinSecrets.has('lantern'))return message('THE WINDOW PANE GRID','The word lock needs the Workshop lantern’s shadow-code.');base('FINAL CABIN SECRET','THE WINDOW WORD LOCK','Enter this run’s four-letter lantern code.');const input=document.createElement('input');input.maxLength=4;input.placeholder='_ _ _ _';const button=document.createElement('button');button.textContent='OPEN THE WORD LOCK';button.onclick=()=>{if(input.value.trim().toUpperCase()===puzzleRun.windowWord){rememberCabinSecret('escaped-window');message('THE CHAIN FALLS',`${puzzleRun.windowWord} opens the lock.`)}else feedback.textContent='The lock refuses that word.'};body.append(input,button)}
}
function openBonusPuzzle(id){controls.unlock();if(bonusSolved.has(id))return message('SECRET ALREADY SOLVED','The hidden compartment is empty. You already recovered its clue.');if(id==='bedside-drawer')return bedsideClockPuzzle();const puzzles={
 'wall-words':['THE SCRATCHED WARNING','The carvings shift after every reset. Rebuild the current sentence from top to bottom.',puzzleRun.hiddenWall,'A photograph inside shows you standing outside the cabin years ago.'],
 'ritual-marks':['THE CABINET MARKINGS','The symbols have rearranged for this playthrough. Follow the glowing marks clockwise.',puzzleRun.hiddenRitual,'A hidden panel reveals that the ritual was meant to imprison—not summon.'],
 'dated-lockbox':['THE HIKER’S LOCKBOX',`This run’s lock asks for the year ${puzzleRun.lockYear} shown on one of the belongings.`,String(puzzleRun.lockYear).split(''),'The box contains a map with the cellar circled in red.'],
 'candle-directions':['THE PUMP DIAGRAM',`The maintenance arrows end at this run’s safe pressure: ${puzzleRun.cellarTarget} PSI.`,['3 PSI','5 PSI','8 PSI',`${puzzleRun.cellarTarget} PSI`],`A note warns: “${puzzleRun.cellarTarget} drains. Anything higher floods.”`],
 'tool-pattern':['THE TOOL CABINET','The tool silhouettes shift after every reset. Follow the current scratches from left to right.',puzzleRun.toolOrder,'The cabinet opens. Someone prepared the bat specifically for your arrival.']};
 const puzzle=puzzles[id];bonusSequencePuzzle(id,...puzzle)}
function bedsideClockPuzzle(){const target=`${puzzleRun.clockHour}:${String(puzzleRun.clockMinute).padStart(2,'0')}`;base('HIDDEN BEDROOM PUZZLE','THE SILENT ALARM CLOCK',`Scratched beneath the clock: “The knocking stopped at ${target}.” Set the frozen clock to that exact time.`);let hour=12,minute=0;const display=document.createElement('div');display.className='handle-count';const controls=document.createElement('div');controls.className='choices';const draw=()=>display.textContent=`${hour}:${String(minute).padStart(2,'0')}`;[['HOUR +1',()=>hour=hour%12+1],['MINUTE +1',()=>minute=(minute+1)%60],['MINUTE +10',()=>minute=(minute+10)%60],['RESET',()=>{hour=12;minute=0}]].forEach(([label,action])=>{const button=document.createElement('button');button.textContent=label;button.onclick=()=>{action();draw();feedback.textContent='The clockwork clicks behind the face.'};controls.append(button)});const wind=document.createElement('button');wind.textContent='WIND THE ALARM';wind.onclick=()=>{if(hour===puzzleRun.clockHour&&minute===puzzleRun.clockMinute){bonusSolved.add('bedside-drawer');localStorage.setItem('cabin-bonus-puzzles',JSON.stringify([...bonusSolved]));feedback.textContent='The alarm rings once. A compartment springs open.';setTimeout(()=>message('THE CLOCK’S COMPARTMENT','Inside is a photograph of the cabin dated one week before you were born.'),600)}else feedback.textContent=`The hands tremble at ${hour}:${String(minute).padStart(2,'0')}, then return to silence.`};draw();body.append(display,controls,wind)}
function bonusSequencePuzzle(id,name,instructions,correct,reward){base('HIDDEN CABIN PUZZLE',name,instructions);let chosen=[];const wrap=document.createElement('div');wrap.className='choices';[...correct].sort(()=>Math.random()-.5).forEach(word=>{const button=document.createElement('button');button.textContent=word;button.onclick=()=>{button.classList.add('used');chosen.push(word);feedback.textContent=chosen.join(' → ');if(chosen.length===correct.length){if(chosen.join()===correct.join()){bonusSolved.add(id);localStorage.setItem('cabin-bonus-puzzles',JSON.stringify([...bonusSolved]));setTimeout(()=>message('SECRET DISCOVERED',reward),450)}else{feedback.textContent='The mechanism rejects that sequence.';setTimeout(()=>bonusSequencePuzzle(id,name,instructions,correct,reward),850)}}};wrap.append(button)});body.append(wrap)}
